11	import { matchGlob } from "./_glob";
12	import { normalizeWindowsPath } from "./_internal";
13	
14	const _UNC_REGEX = /^[/\\]{2}/;
15	const _IS_ABSOLUTE_RE = /^[/\\](?![/\\])|^[/\\]{2}(?!\.)|^[A-Za-z]:[/\\]/;
16	const _DRIVE_LETTER_RE = /^[A-Za-z]:$/;
17	const _ROOT_FOLDER_RE = /^\/([A-Za-z]:)?$/;
18	const _EXTNAME_RE = /.(\.[^./]+|\.)$/;
19	const _PATH_ROOT_RE = /^[/\\]|^[a-zA-Z]:[/\\]/;
20	
21	/**
22	 * Constant for path separator.
23	 *
24	 * Always equals to `"/"`.
25	 */
26	export const sep = "/";
27	
28	export const normalize: typeof path.normalize = function (path: string) {
29	  if (path.length === 0) {
30	    return ".";
31	  }
32	
33	  // Normalize windows argument
34	  path = normalizeWindowsPath(path);
35	
36	  const isUNCPath = path.match(_UNC_REGEX);
37	  const isPathAbsolute = isAbsolute(path);
38	  const trailingSeparator = path[path.length - 1] === "/";
39	
40	  // Normalize the path
41	  path = normalizeString(path, !isPathAbsolute);
42	
43	  if (path.length === 0) {
44	    if (isPathAbsolute) {
45	      return "/";
46	    }
47	    return trailingSeparator ? "./" : ".";
48	  }
49	  if (trailingSeparator) {
50	    path += "/";
51	  }
52	  if (_DRIVE_LETTER_RE.test(path)) {
53	    path += "/";
54	  }
55	
56	  if (isUNCPath) {
57	    if (!isPathAbsolute) {
58	      return `//./${path}`;
59	    }
60	    return `//${path}`;
61	  }
62	
63	  return isPathAbsolute && !isAbsolute(path) ? `/${path}` : path;
64	};
65	
66	export const join: typeof path.join = function (...segments) {
67	  let path = "";
68	
69	  for (const seg of segments) {
70	    if (!seg) {
71	      continue;
72	    }
73	    if (path.length > 0) {
74	      const pathTrailing = path[path.length - 1] === "/";
75	      const segLeading = seg[0] === "/";
76	      const both = pathTrailing && segLeading;
77	      if (both) {
78	        path += seg.slice(1);
79	      } else {
80	        path += pathTrailing || segLeading ? seg : `/${seg}`;
81	      }
82	    } else {
