100	
101	  let resolvedPath = "";
102	  let resolvedAbsolute = false;
103	
104	  for (let index = arguments_.length - 1; index >= -1 && !resolvedAbsolute; index--) {
105	    const path = index >= 0 ? arguments_[index] : cwd();
106	
107	    // Skip empty entries
108	    if (!path || path.length === 0) {
109	      continue;
110	    }
111	
112	    resolvedPath = `${path}/${resolvedPath}`;
113	    resolvedAbsolute = isAbsolute(path);
114	  }
