129	/**
130	 * Resolves a string path, resolving '.' and '.' segments and allowing paths above the root.
131	 *
132	 * @param path - The path to normalise.
133	 * @param allowAboveRoot - Whether to allow the resulting path to be above the root directory.
134	 * @returns the normalised path string.
135	 */
136	export function normalizeString(path: string, allowAboveRoot: boolean) {
137	  let res = "";
138	  let lastSegmentLength = 0;
139	  let lastSlash = -1;
140	  let dots = 0;
141	  let char: string | null = null;
142	  for (let index = 0; index <= path.length; ++index) {
143	    if (index < path.length) {
144	      // casted because we know it exists thanks to the length check
145	      char = path[index] as string;
146	    } else if (char === "/") {
147	      break;
148	    } else {
149	      char = "/";
150	    }
151	    if (char === "/") {
152	      if (lastSlash === index - 1 || dots === 1) {
153	        // NOOP
154	      } else if (dots === 2) {
155	        if (
156	          res.length < 2 ||
157	          lastSegmentLength !== 2 ||
158	          res[res.length - 1] !== "." ||
159	          res[res.length - 2] !== "."
160	        ) {
161	          if (res.length > 2) {
162	            const lastSlashIndex = res.length - lastSegmentLength - 1;
163	            if (lastSlashIndex === -1) {
164	              res = "";
165	              lastSegmentLength = 0;
166	            } else {
167	              res = res.slice(0, lastSlashIndex);
168	              lastSegmentLength = res.length - 1 - res.lastIndexOf("/");
169	            }
170	            lastSlash = index;
171	            dots = 0;
172	            continue;
173	          } else if (res.length > 0) {
174	            res = "";
175	            lastSegmentLength = 0;
176	            lastSlash = index;
177	            dots = 0;
178	            continue;
179	          }
180	        }
181	        if (allowAboveRoot) {
182	          res += res.length > 0 ? "/.." : "..";
183	          lastSegmentLength = 2;
184	        }
185	      } else {
186	        if (res.length > 0) {
187	          res += `/${path.slice(lastSlash + 1, index)}`;
188	        } else {
189	          res = path.slice(lastSlash + 1, index);
190	        }
191	        lastSegmentLength = index - lastSlash - 1;
192	      }
193	      lastSlash = index;
194	      dots = 0;
195	    } else if (char === "." && dots !== -1) {
196	      ++dots;
197	    } else {
198	      dots = -1;
199	    }
200	  }
201	  return res;
202	}
