212	export const extname: typeof path.extname = function (p) {
213	  // Resolve the extension from the last path segment only, so a separator or
214	  // trailing slash earlier in the input does not leak into the result. This
215	  // keeps `extname()` in agreement with `parse().ext` and `node:path`.
216	  const base = basename(p);
217	  if (base === "..") return "";
